fn main() {
    let mut entries = vec![
        Entry { name: "Zoe", score: 9, penalty: 0 },
        Entry { name: "Ava", score: 15, penalty: 2 },
        Entry { name: "Bea", score: 15, penalty: 1 },
        Entry { name: "Cy", score: 12, penalty: 3 },
        Entry { name: "Dan", score: 12, penalty: 0 },
        Entry { name: "Eli", score: 15, penalty: 1 },
    ];

    entries.sort_by(|a, b| {
