pub fn leaderboard(entries: &[(&str, u32, u32)]) -> Vec<String> {
    let mut rows: Vec<(&str, u32, u32)> = entries.to_vec();
    rows.sort_by(|a, b| {
        b.1.cmp(&a.1)
            .then(a.2.cmp(&b.2))
            .then(a.0.cmp(&b.0))
    });

    rows.into_iter()
        .map(|(name, score, penalty)| format!("{}:{}:{}", name, score, penalty))
        .collect()
}

